<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');if($_SERVER['REQUEST_METHOD']==='POST'){$q=$db->prepare('INSERT INTO staff_members(employee_code,first_name,last_name,email,phone,department,job_title,hourly_rate,currency,availability_hours) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([trim($_POST['employee_code']),trim($_POST['first_name']),trim($_POST['last_name']),trim($_POST['email']),trim($_POST['phone']??''),trim($_POST['department']??''),trim($_POST['job_title']??''),(float)($_POST['hourly_rate']??0),$_POST['currency']??'USD',(float)($_POST['availability_hours']??40)]);header('Location: team.php');exit;}$rows=$db->query('SELECT * FROM staff_members ORDER BY first_name,last_name')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Team</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Team & Staff</h1><div class="card mb-4"><div class="card-body"><form method="post" class="row g-2"><div class="col-md-2"><input class="form-control" name="employee_code" placeholder="EMP-001" required></div><div class="col-md-2"><input class="form-control" name="first_name" placeholder="First name" required></div><div class="col-md-2"><input class="form-control" name="last_name" placeholder="Last name" required></div><div class="col-md-3"><input class="form-control" type="email" name="email" placeholder="Email" required></div><div class="col-md-3"><input class="form-control" name="phone" placeholder="Phone"></div><div class="col-md-3"><input class="form-control" name="department" placeholder="Department"></div><div class="col-md-3"><input class="form-control" name="job_title" placeholder="Job title"></div><div class="col-md-2"><input class="form-control" type="number" step="0.01" name="hourly_rate" placeholder="Hourly rate"></div><div class="col-md-2"><input class="form-control" name="currency" value="USD"></div><div class="col-md-2"><input class="form-control" type="number" step="0.25" name="availability_hours" value="40"></div><div class="col-md-12"><button class="btn btn-dark">Add Staff Member</button></div></form></div></div><div class="card"><div class="card-body"><table class="table"><thead><tr><th>Employee</th><th>Email</th><th>Department</th><th>Role</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$e($r['employee_code'])?> — <?=$e($r['first_name'].' '.$r['last_name'])?></td><td><?=$e($r['email'])?></td><td><?=$e($r['department'])?></td><td><?=$e($r['job_title'])?></td><td><?=$e($r['employment_status'])?></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>